import { cpSync, mkdirSync, rmSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { defineConfig, devices } from "@playwright/test";
import { E2E_CATALOG_DIR, E2E_SOURCES_DIR } from "./e2e/paths";

// Dedicated ports so the smoke test never reuses (or collides with) your dev servers.
const API_PORT = 8010;
const WEB_PORT = 5180;
const repoRoot = fileURLToPath(new URL("../..", import.meta.url));

// The API under test serves a fresh copy of the catalog library, so models generated by the
// tests (and deleted by the missing-model test) never touch the developer's library. Workers
// load this file too; only the main process (no worker index) prepares the folder.
if (!process.env.TEST_WORKER_INDEX) {
  rmSync(E2E_CATALOG_DIR, { recursive: true, force: true });
  mkdirSync(E2E_CATALOG_DIR, { recursive: true });
  cpSync(`${repoRoot}assets/catalog/models`, `${E2E_CATALOG_DIR}/models`, { recursive: true });
  // Photos stored by the photo-import tests (and removed by the missing-photo test).
  rmSync(E2E_SOURCES_DIR, { recursive: true, force: true });
  mkdirSync(E2E_SOURCES_DIR, { recursive: true });
}

export default defineConfig({
  testDir: "e2e",
  // The public-preview journeys run against the production build (playwright.public.config.ts).
  testIgnore: ["public/**"],
  fullyParallel: false,
  // Headless Chromium renders WebGL in software; two workers keep frames (and the React
  // commits behind each assertion) responsive, and WebGL-heavy checks get extra time.
  workers: 2,
  // CI runners have no GPU: every frame is rendered in software, so a test that drives the
  // camera takes several times longer there than locally.
  timeout: process.env.CI ? 60_000 : 30_000,
  expect: { timeout: 15_000 },
  forbidOnly: Boolean(process.env.CI),
  retries: 0,
  reporter: [["list"]],
  use: {
    baseURL: `http://127.0.0.1:${WEB_PORT}`,
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
    // Existing tests open the editor directly; the guided start panel has its own tests, which
    // start with empty storage.
    // They also show the advanced panels (Details); the simple screen has its own tests.
    storageState: {
      cookies: [],
      origins: [
        {
          origin: `http://127.0.0.1:${WEB_PORT}`,
          localStorage: [
            { name: "rws.start.seen", value: "1" },
            { name: "rws.details", value: "1" },
          ],
        },
      ],
    },
  },
  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"], viewport: { width: 1440, height: 900 } } },
  ],
  webServer: [
    {
      command: "uv run python -m replay_world_api",
      cwd: repoRoot,
      url: `http://127.0.0.1:${API_PORT}/health`,
      // Language proposals come from recorded live answers (labelled "recorded", never shown as
      // live AI); the repository .env (and any API key in it) is not read.
      env: {
        RWS_API_PORT: String(API_PORT),
        RWS_CORS_ORIGINS: `http://127.0.0.1:${WEB_PORT}`,
        RWS_ENV_FILE: "none",
        RWS_ASSIST_PROVIDER: "recorded",
        RWS_CATALOG_DIR: E2E_CATALOG_DIR,
        RWS_SOURCES_DIR: E2E_SOURCES_DIR,
      },
      reuseExistingServer: false,
      timeout: 60_000,
    },
    {
      command: `pnpm exec vite --port ${WEB_PORT} --strictPort`,
      url: `http://127.0.0.1:${WEB_PORT}`,
      env: { VITE_API_BASE_URL: `http://127.0.0.1:${API_PORT}` },
      reuseExistingServer: false,
      timeout: 60_000,
    },
  ],
});
